mapper.select:
SELECT id, user_id, status, goods_amount, discount_amount, freight_amount,
       pay_amount, coupon_name, address_snapshot, created_at, payment_expires_at
FROM customer_order WHERE user_id = #{userId} ORDER BY created_at DESC LIMIT #{limit}

SELECT id, user_id, status, goods_amount, discount_amount, freight_amount,
       pay_amount, coupon_name, address_snapshot, created_at, payment_expires_at
FROM customer_order WHERE user_id = #{userId} AND id = #{orderId}

mapper.update:
UPDATE product_sku SET stock = stock - #{quantity}, locked_stock = locked_stock + #{quantity}
WHERE id = #{skuId} AND enabled = TRUE AND stock >= #{quantity} AND price=#{expectedPrice}
  AND EXISTS (SELECT 1 FROM product p WHERE p.id=product_sku.product_id AND p.enabled=TRUE)
